from typing import List

class Solution:
    def numFactoredBinaryTrees(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        arr.sort()
        index = {v:i for i,v in enumerate(arr)}
        n = len(arr)
        dp = [1] * n  # single node tree for each value
        for i in range(n):
            ai = arr[i]
            for j in range(i):
                aj = arr[j]
                if ai % aj == 0:
                    other = ai // aj
                    k = index.get(other)
                    if k is not None:
                        dp[i] = (dp[i] + dp[j] * dp[k]) % MOD
        return sum(dp) % MOD
